/**
 *
 * The useSortable hook provides per-item sortable state.
 * Used with useDnd coordinator to derive isDragging for individual items.
 *
 * @module useSortable
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
import type { UniqueId } from '@primereact/types/primitive/dnd';
/**
 * Defines valid properties in useSortable.
 */
export interface UseSortableProps {
    /**
     * The DnD coordinator instance (from useDnd).
     */
    dnd?: unknown;
    /**
     * Unique identifier for this sortable item.
     */
    id?: UniqueId;
    /**
     * The index of this item in its container.
     */
    index?: number;
    /**
     * Whether the sortable item is disabled.
     * @default false
     */
    disabled?: boolean;
}
/**
 * Defines valid state in useSortable.
 */
export interface UseSortableState {
    /**
     * Whether this item is currently being dragged.
     */
    isDragging: boolean;
}
/**
 * Data attribute props for the sortable item element.
 */
export interface UseSortableRootProps {
    'data-scope': string;
    'data-part': string;
    'data-dragging'?: string;
    'data-disabled'?: string;
}
/**
 * Defines the methods and properties exposed by useSortable.
 */
export interface UseSortableExposes {
    /**
     * The reactive sortable item state.
     */
    state: UseSortableState;
    /**
     * Pre-built data attribute props for the sortable element.
     */
    rootProps: UseSortableRootProps;
}
/**
 * Instance of useSortable headless.
 */
export type UseSortableInstance = HeadlessInstance<UseSortableProps, UseSortableState, UseSortableExposes>;
